-- Phase 8: Post-Import Assertions
DO $$
DECLARE
    c INT;
    uuid_val UUID;
BEGIN
    SELECT count(*) INTO c FROM geo_states;
    IF c != 36 THEN RAISE EXCEPTION 'Assertion failed: expected 36 states, got %', c; END IF;
    SELECT count(*) INTO c FROM geo_districts;
    IF c != 784 THEN RAISE EXCEPTION 'Assertion failed: expected 784 districts, got %', c; END IF;
    SELECT count(*) INTO c FROM geo_subdistricts;
    IF c != 7092 THEN RAISE EXCEPTION 'Assertion failed: expected 7092 subdistricts, got %', c; END IF;

    -- A. District → State relational integrity (NOT EXISTS)
    IF EXISTS (
        SELECT 1 FROM geo_districts d
        LEFT JOIN geo_states s ON s.state_id = d.state_id
        WHERE s.state_id IS NULL
    ) THEN
        RAISE EXCEPTION 'Post-condition failed: district references non-existent state';
    END IF;

    -- B. Subdistrict → District relational integrity (NOT EXISTS on composite FK)
    IF EXISTS (
        SELECT 1 FROM geo_subdistricts sd
        LEFT JOIN geo_districts d
            ON d.state_id = sd.state_id AND d.district_id = sd.district_id
        WHERE d.district_id IS NULL
    ) THEN
        RAISE EXCEPTION 'Post-condition failed: subdistrict references non-existent district';
    END IF;

    -- C. Subdistrict state_id parity with parent district state_id
    IF EXISTS (
        SELECT 1 FROM geo_subdistricts sd
        JOIN geo_districts d ON d.district_id = sd.district_id
        WHERE sd.state_id <> d.state_id
    ) THEN
        RAISE EXCEPTION 'Post-condition failed: subdistrict state_id does not match district state_id';
    END IF;

    -- D. LGD code uniqueness (defense-in-depth)
    SELECT count(*) INTO c FROM geo_states;
    IF c != (SELECT count(DISTINCT lgd_code) FROM geo_states) THEN
        RAISE EXCEPTION 'Post-condition failed: duplicate lgd_code in geo_states';
    END IF;
    SELECT count(*) INTO c FROM geo_districts;
    IF c != (SELECT count(DISTINCT lgd_code) FROM geo_districts) THEN
        RAISE EXCEPTION 'Post-condition failed: duplicate lgd_code in geo_districts';
    END IF;
    SELECT count(*) INTO c FROM geo_subdistricts;
    IF c != (SELECT count(DISTINCT lgd_code) FROM geo_subdistricts) THEN
        RAISE EXCEPTION 'Post-condition failed: duplicate lgd_code in geo_subdistricts';
    END IF;

    -- E. State 7 explicit name/type/UUID assertion
    SELECT state_id INTO uuid_val FROM geo_states WHERE lgd_code = '7';
    IF uuid_val IS NULL OR uuid_val != '425d54c4-c3b9-44ca-ba33-bb18ef4d1bdc'::uuid THEN
        RAISE EXCEPTION 'Post-condition failed: State 7 UUID changed';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM geo_states
        WHERE lgd_code = '7' AND name = 'Delhi' AND type = 'UT'
    ) THEN
        RAISE EXCEPTION 'Post-condition failed: State 7 name/type mismatch after import';
    END IF;

    SELECT state_id INTO uuid_val FROM geo_states WHERE lgd_code = '27';
    IF uuid_val IS NULL OR uuid_val != '3bfe7242-41c8-4eeb-90d2-f53a0ed9679f'::uuid THEN RAISE EXCEPTION 'Assertion failed: State 27 UUID drifted'; END IF;
    SELECT state_id INTO uuid_val FROM geo_states WHERE lgd_code = '9';
    IF uuid_val IS NULL OR uuid_val != 'a78df465-0ec0-42bb-854d-2af7b406ef90'::uuid THEN RAISE EXCEPTION 'Assertion failed: State 9 UUID drifted'; END IF;
    SELECT state_id INTO uuid_val FROM geo_states WHERE lgd_code = '7';
    IF uuid_val IS NULL OR uuid_val != '425d54c4-c3b9-44ca-ba33-bb18ef4d1bdc'::uuid THEN RAISE EXCEPTION 'Assertion failed: State 7 UUID drifted'; END IF;
    SELECT district_id INTO uuid_val FROM geo_districts WHERE lgd_code = '490';
    IF uuid_val IS NULL OR uuid_val != 'c752faed-ece4-4cb6-96cc-fa6184ea4c3e'::uuid THEN RAISE EXCEPTION 'Assertion failed: District 490 UUID drifted'; END IF;
    SELECT district_id INTO uuid_val FROM geo_districts WHERE lgd_code = '482';
    IF uuid_val IS NULL OR uuid_val != 'a4925aa4-9c0e-45ac-b1d7-90232de58bd3'::uuid THEN RAISE EXCEPTION 'Assertion failed: District 482 UUID drifted'; END IF;
    SELECT district_id INTO uuid_val FROM geo_districts WHERE lgd_code = '483';
    IF uuid_val IS NULL OR uuid_val != '8118d7ef-375b-4c76-88a0-6b1c3db11f00'::uuid THEN RAISE EXCEPTION 'Assertion failed: District 483 UUID drifted'; END IF;
    SELECT district_id INTO uuid_val FROM geo_districts WHERE lgd_code = '484';
    IF uuid_val IS NULL OR uuid_val != '05eebd51-6842-4a35-b36d-1247728d1b1f'::uuid THEN RAISE EXCEPTION 'Assertion failed: District 484 UUID drifted'; END IF;
    SELECT district_id INTO uuid_val FROM geo_districts WHERE lgd_code = '487';
    IF uuid_val IS NULL OR uuid_val != '25459d3d-f91d-4d08-93db-57db7fdf6ea7'::uuid THEN RAISE EXCEPTION 'Assertion failed: District 487 UUID drifted'; END IF;
    SELECT district_id INTO uuid_val FROM geo_districts WHERE lgd_code = '469';
    IF uuid_val IS NULL OR uuid_val != '359dfd30-4599-4558-91ed-b06fb8f276a1'::uuid THEN RAISE EXCEPTION 'Assertion failed: District 469 UUID drifted'; END IF;
    SELECT district_id INTO uuid_val FROM geo_districts WHERE lgd_code = '497';
    IF uuid_val IS NULL OR uuid_val != '19a80993-fa28-499c-8070-2e7ec3f4c2d0'::uuid THEN RAISE EXCEPTION 'Assertion failed: District 497 UUID drifted'; END IF;
    SELECT district_id INTO uuid_val FROM geo_districts WHERE lgd_code = '480';
    IF uuid_val IS NULL OR uuid_val != '47f38108-0257-44ff-a512-3761e58fe173'::uuid THEN RAISE EXCEPTION 'Assertion failed: District 480 UUID drifted'; END IF;
    SELECT subdistrict_id INTO uuid_val FROM geo_subdistricts WHERE lgd_code = '4194';
    IF uuid_val IS NULL OR uuid_val != '0a7fdfde-fc1f-443c-a1ae-5ebbb5a79f2f'::uuid THEN RAISE EXCEPTION 'Assertion failed: Subdistrict 4194 UUID drifted'; END IF;
    SELECT subdistrict_id INTO uuid_val FROM geo_subdistricts WHERE lgd_code = '4193';
    IF uuid_val IS NULL OR uuid_val != '2dad72bb-022f-4a1c-a841-6a49f41086dc'::uuid THEN RAISE EXCEPTION 'Assertion failed: Subdistrict 4193 UUID drifted'; END IF;
    SELECT subdistrict_id INTO uuid_val FROM geo_subdistricts WHERE lgd_code = '4190';
    IF uuid_val IS NULL OR uuid_val != '1eced13f-a82a-443a-8e69-2c4ae6794bad'::uuid THEN RAISE EXCEPTION 'Assertion failed: Subdistrict 4190 UUID drifted'; END IF;
    SELECT subdistrict_id INTO uuid_val FROM geo_subdistricts WHERE lgd_code = '4189';
    IF uuid_val IS NULL OR uuid_val != '33a06723-cfa4-42d5-9cf9-1d946dbda2c5'::uuid THEN RAISE EXCEPTION 'Assertion failed: Subdistrict 4189 UUID drifted'; END IF;
END $$;
